const limit = 25;
const query = 'newer_than:14d';
const accountKey = '';
const runId = '';
const enableM1 = false;
const ingestionId = '';
const configurationRevisionId = null;
if (!Number.isInteger(limit) || limit < 1 || limit > 25) throw new Error('Invalid message limit');
if (typeof query !== 'string') throw new Error('Invalid query');
if (enableM1) {
  const { createHistoricalState, openHistoricalForN8n } = require('mailflow-pipeline');
  const config = { ingestionId, accountKey, query, pageSize: limit, maxMessages: limit, enableM1, configurationRevisionId };
  createHistoricalState(config);
  return [{ json: { enableM1, limit, query, accountKey, state: await openHistoricalForN8n(config) } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(runId)) throw new Error('Configure an explicit run UUID before execution');
if (!/^[A-Za-z0-9_-]{1,128}$/.test(accountKey)) throw new Error('Invalid account key');
return [{ json: { enableM1, limit, query, accountKey, runId } }];

const { prepareGmailMessageList, prepareHistoricalPage } = require('mailflow-pipeline');
const config = $('Configure Persistence Run').first().json;
if (config.enableM1) {
  const page = prepareHistoricalPage(config.state, $input.first()?.json);
  const base = { previousState: config.state, page };
  return page.messages.length ? page.messages.map((message) => ({ json: { hasMessage: true, ...message, ...base } })) : [{ json: { hasMessage: false, ...base } }];
}
const messages = prepareGmailMessageList($input.first()?.json, config.limit);
return messages.length ? messages.map((message) => ({ json: { hasMessage: true, ...message } })) : [{ json: { hasMessage: false } }];

const config = $('Configure Persistence Run').first().json;
const requests = $('Prepare Message IDs').all();
const responses = $input.all();
if (config.enableM1) {
  if (responses.length !== requests.length || requests.length > 25) throw new Error('Gmail response count does not match requests');
  const ordered = new Array(requests.length);
  for (const response of responses) {
    const index = response.pairedItem?.item;
    if (!Number.isInteger(index) || index < 0 || index >= requests.length || ordered[index]) throw new Error('Invalid Gmail response association');
    ordered[index] = { json: { messageId: requests[index].json.id, statusCode: response.json?.statusCode, hasError: Boolean(response.json?.error), body: response.json?.body } };
  }
  return ordered;
}
const { processGmailResponse } = require('mailflow-pipeline');
if (responses.length !== requests.length || requests.length > 25) throw new Error('Gmail response count does not match requests');
const processed = new Array(requests.length);
for (const response of responses) {
  const index = response.pairedItem?.item;
  if (!Number.isInteger(index) || index < 0 || index >= requests.length || processed[index]) throw new Error('Invalid Gmail response association');
  processed[index] = { json: processGmailResponse(requests[index].json.id, response.json, index + 1) };
}
return processed;

const config = $('Configure Persistence Run').first().json;
if (config.enableM1) {
  const pageInfo = $('Prepare Message IDs').first().json;
  const { persistVersionedLivePageForN8n } = require('mailflow-pipeline');
  return [{ json: await persistVersionedLivePageForN8n(pageInfo.previousState, pageInfo.page, $input.all().map((item) => item.json)) }];
}
const { persistForN8n } = require('mailflow-pipeline');
return [{ json: await persistForN8n(config.runId, config.accountKey, $input.all().map((item) => item.json)) }];

const config = $('Configure Persistence Run').first().json;
if (config.enableM1) {
  const pageInfo = $('Prepare Message IDs').first().json;
  const { persistVersionedLivePageForN8n } = require('mailflow-pipeline');
  return [{ json: await persistVersionedLivePageForN8n(pageInfo.previousState, pageInfo.page, []) }];
}
const { persistForN8n } = require('mailflow-pipeline');
return [{ json: await persistForN8n(config.runId, config.accountKey, []) }];

const { historicalReport } = require('mailflow-pipeline');
const state = $('Configure Persistence Run').first().json.state;
return [{ json: { schemaVersion: '2.0', ...historicalReport(state), configuration: { configurationRevisionId: state.versionedEvaluation.configurationRevisionId }, currentEffectiveSelected: 0, results: [] } }];
